import {renderMarkdown} from './markdown.js';
import {storageKey,readStore,contextFor,createChat} from './chat-store.js';
import {normaliseUsage,sumUsage} from './usage.js';
import {stages,labels,elapsed,stageFor} from './progress.js';
const $=id=>document.getElementById(id);let endpoint='',busy=false;
try{const initial=new URLSearchParams(location.hash.slice(1)).get('bridge');const saved=initial||localStorage.getItem('taiwan-cli-endpoint')||sessionStorage.getItem('taiwan-cli-endpoint');if(saved){const url=new URL(saved);if(url.protocol==='https:'&&url.hostname.endsWith('.workers.dev')){endpoint=url.href.replace(/\/$/,'');try{localStorage.setItem('taiwan-cli-endpoint',endpoint)}catch{}}}if(initial)window.history.replaceState(null,'',location.pathname);}catch{}
let storage;try{storage=window.localStorage}catch{}
let store=readStore(storage);if(!store.chats.length){const chat=createChat();store.chats.push(chat);store.active=chat.id;}
const active=()=>store.chats.find(c=>c.id===store.active);
let progressTimer=null,progressStage='queued',progressStart=0;
function updateProgress(stage=progressStage){progressStage=stage;$('progress').hidden=false;$('progress-label').textContent=labels[stage];$('elapsed').textContent='経過 '+elapsed(progressStart);const index=stages.indexOf(stage);for(const [i,node] of [...$('progress-steps').children].entries()){node.classList.toggle('current',i===index);node.classList.toggle('done',i<index);if(i===index)node.setAttribute('aria-current','step');else node.removeAttribute('aria-current');}}
function startProgress(chat){progressStart=chat.pending?.startedAt||Date.now();updateProgress();clearInterval(progressTimer);progressTimer=setInterval(()=>{$('elapsed').textContent='経過 '+elapsed(progressStart);},1000);}
function stopProgress(){clearInterval(progressTimer);$('progress').hidden=true;}
let storageError=false;function save(){try{localStorage.setItem(storageKey,JSON.stringify(store));storageError=false}catch{storageError=true;$('status').textContent='この端末に履歴を保存できません。画面を閉じると会話が失われる場合があります。';}}
const app=document.querySelector('.app');
try{app.classList.toggle('history-collapsed',localStorage.getItem('taiwan-chat-history-collapsed')==='true');}catch{}
function menu(open,explicit=false){const narrow=matchMedia('(max-width:750px)').matches;if(narrow){$('sidebar').classList.toggle('is-open',open);$('shade').hidden=!open;}else if(explicit){app.classList.toggle('history-collapsed',!open);try{localStorage.setItem('taiwan-chat-history-collapsed',String(!open));}catch{}}$('open-menu').setAttribute('aria-expanded',String(narrow?open:!app.classList.contains('history-collapsed')));}
$('open-menu').onclick=()=>menu(true,true);$('close-menu').onclick=()=>menu(false,true);$('shade').onclick=()=>menu(false);document.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false);});
function renderUsage(chat){const sum=sumUsage(chat.messages);$('usage-total').hidden=!sum.count;$('usage-summary').textContent='この会話：'+sum.total.toLocaleString('ja-JP')+' トークン';$('usage-detail').textContent=`入力 ${sum.input.toLocaleString('ja-JP')} / 出力 ${sum.output.toLocaleString('ja-JP')}（入力のうちキャッシュ済み ${sum.cached==null?'未取得':sum.cached.toLocaleString('ja-JP')}）`;$('usage-note').textContent=`取得できた${sum.count}回答分の累計です。${sum.unknown?'過去の未取得分は含みません。':''}プランの残り利用枠や料金を示すものではありません。`;}
function renderList(){const holder=$('conversations');holder.replaceChildren();[...store.chats].sort((a,b)=>b.updatedAt-a.updatedAt).forEach(chat=>{const button=document.createElement('button');button.type='button';button.textContent=chat.title;button.title=chat.title;if(chat.id===store.active)button.setAttribute('aria-current','page');button.disabled=busy;button.onclick=()=>{store.active=chat.id;save();render();menu(false);if(chat.pending?.id)resume(chat);};holder.append(button);});}
function render(){const chat=active();document.title=chat.title+' · 丹陽さん';$('chat-title').textContent=chat.title;$('welcome').hidden=chat.messages.length>0;$('delete-chat').disabled=busy||!chat.messages.length;$('messages').replaceChildren();for(const item of chat.messages){const row=document.createElement('article');row.className='message '+item.role;const label=document.createElement('small');label.textContent=item.role==='user'?'あなた':'丹陽さん';const text=document.createElement('div');text.innerHTML=renderMarkdown(item.content);row.append(label,text);if(item.role==='assistant'){const usage=normaliseUsage(item.usage);const info=document.createElement('small');info.className='message-usage';info.textContent=usage?`入力 ${usage.input_tokens.toLocaleString('ja-JP')} / 出力 ${usage.output_tokens.toLocaleString('ja-JP')}${usage.cached_input_tokens!=null?' / 入力内キャッシュ '+usage.cached_input_tokens.toLocaleString('ja-JP'):''} トークン`:'トークン使用量は未取得';if(usage?.cached_input_tokens!=null)info.title=`入力のうちキャッシュ済み ${usage.cached_input_tokens.toLocaleString('ja-JP')} トークン`;row.append(info);}$('messages').append(row);}$('retry').hidden=!chat.error||busy;$('status').textContent=chat.error||(storageError?'この端末に履歴を保存できません。':!endpoint?'専用の起動リンクから開いてください。':'');renderUsage(chat);renderList();requestAnimationFrame(()=>{$('scroll-area').scrollTop=$('scroll-area').scrollHeight;});}
function setBusy(value){busy=value;$('send').disabled=value;$('question').disabled=value;$('new-chat').disabled=value;$('delete-chat').disabled=value||!active().messages.length;$('retry').hidden=value||!active().error;renderList();}
async function api(path,options={}){const r=await fetch(endpoint+path,{...options,referrerPolicy:'no-referrer',signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok||data.error)throw Error(data.error||'接続できませんでした。');return data;}
async function poll(chat){for(let attempt=0;attempt<180;attempt++){if(attempt)await new Promise(resolve=>setTimeout(resolve,2500));const result=await api('/jobs/'+chat.pending.id);if(result.status==='completed'){if(typeof result.answer!=='string'||!result.answer.trim())throw Error('回答を取得できませんでした。');chat.messages.push({role:'assistant',content:result.answer,usage:normaliseUsage(result.usage)});chat.pending=null;chat.error='';chat.updatedAt=Date.now();save();render();$('status').textContent=storageError?'履歴を端末に保存できませんでした。':' ';return}if(result.status==='failed'){chat.pending=null;throw Error(result.error||'実行に失敗しました。');}updateProgress(stageFor(result));$('status').textContent='';}throw Error('まだ実行が終わっていません。「再試行」で回答の取得を再開できます。');}
async function resume(chat){if(busy||!endpoint)return;setBusy(true);chat.error='';progressStage='queued';startProgress(chat);try{if(!chat.pending?.id){$('status').textContent='送信しています…';const {id}=await api('/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:contextFor(chat)})});chat.pending={id,startedAt:progressStart};save();}await poll(chat);}catch(error){chat.error=error.message;save();$('status').textContent=chat.error;}finally{stopProgress();setBusy(false);$('question').focus();}}
$('new-chat').onclick=()=>{if(busy)return;const current=active();if(!current.messages.length){menu(false);return;}const chat=createChat();store.chats.push(chat);store.active=chat.id;save();render();menu(false);$('question').focus();};
$('delete-chat').onclick=()=>{if(busy||!confirm('この端末から、この会話の履歴を削除しますか？'))return;store.chats=store.chats.filter(c=>c.id!==store.active);if(!store.chats.length)store.chats.push(createChat());store.active=store.chats[0].id;save();render();};
$('retry').onclick=()=>resume(active());
$('chat-form').onsubmit=async event=>{event.preventDefault();if(busy)return;if(!endpoint){$('status').textContent='専用の起動リンクから開いてください。';return;}const text=$('question').value.trim();if(!text)return;const chat=active();if(chat.pending?.id){$('status').textContent='前の回答を「再試行」で取得してから送信してください。';return;}chat.error='';chat.messages.push({role:'user',content:text});if(chat.messages.filter(m=>m.role==='user').length===1)chat.title=text.slice(0,32);chat.updatedAt=Date.now();save();$('question').value='';render();await resume(chat);};
for(const button of document.querySelectorAll('.suggestions button'))button.onclick=()=>{$('question').value=button.textContent;$('question').focus();};
$('question').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)&&!event.isComposing){event.preventDefault();$('chat-form').requestSubmit();}});
menu(false);render();if(active().pending?.id&&endpoint)resume(active());
